/** Owning detached pipeline, not ordinary write activation. */
final class ContextUniversalNativeBranchMatrix {
    static int pipelines,checksOfPipeline;
    static Policy policy(int rounds,int work,int capacity){return new Policy(ContextUniversalGroupedRoundsRunner.limits(16),ContextUniversalGroupedRoundsRunner.local(),rounds,work,capacity);}
    static Receipt stable(Result r,Snapshot x,List<Snapshot> cuts,Policy p){require(r.status==Status.STABLE_SUPPLIED&&r.output!=null&&r.refutations.isEmpty(),r.phase+": "+r.reason);Receipt receipt=r.output;require(receipt.x==x&&receipt.foreign.equals(cuts)&&receipt.policy==p&&receipt.initial.entry.common==receipt.chain.input,"sealed actual original request/initial-to-terminal binding");++pipelines;++audits;ContextUniversalNativeBranch.check(receipt,x,cuts,p,WORK,4096);++checksOfPipeline;++receipts;require(receipt.chain.trace.status==org.kanger.ContextUniversalGroupedRounds.Status.STABLE_GROUPED_POOLS,"pipeline receipt contains actual stable controller chain");return receipt;}
    static void no(Result r,String why){require(r.status==Status.INCOMPLETE&&r.output==null&&r.refutations.isEmpty(),why+": "+r.status+"/"+r.phase+": "+r.reason);}
    static void recheckFails(Receipt r,Snapshot x,List<Snapshot> cuts,Policy p,int work,String why){boolean failed=false;try{ContextUniversalNativeBranch.check(r,x,cuts,p,work,4096);}catch(IllegalStateException|IllegalArgumentException expected){failed=true;}require(failed,why);}
    static void continued(Receipt r){org.kanger.ContextUniversalGroupedRounds.Result before=r.chain.trace;Policy p=r.policy;org.kanger.ContextUniversalGroupedRounds.SessionRun next=ContextUniversalGroupedRounds.runWithValidationReuse(r.x,r.foreign,before.output.packet,before.output.privatePools,before.symbolicOutput,before.compoundOutput,p.kernel,p.local,1,WORK,4096);require(next.result.status==org.kanger.ContextUniversalGroupedRounds.Status.STABLE_GROUPED_POOLS&&next.result.completedRounds==1&&next.metrics.entries==0,"actual owning pipeline output supports one stable continuation");org.kanger.ContextUniversalGroupedChainAudit.SessionInspection audit=org.kanger.ContextUniversalGroupedChainAudit.inspectWithValidationReuse(r.x,r.foreign,before.output.packet,before.output.privatePools,before.symbolicOutput,before.compoundOutput,p.kernel,p.local,1,next.result,WORK,4096);require(audit.inspection.audited&&audit.metrics.entries==0,audit.inspection.reason);++audits;require(org.kanger.ContextUniversalGroupedChainAudit.checkWithValidationReuse(audit.inspection.output,WORK,4096).entries==0,"fresh continued receipt recheck");++receipts;++continuations;same(before,next.result);}
    static void manual(Receipt r){org.kanger.ContextUniversalInitialEntry.Entry e=r.initial.entry;org.kanger.ContextUniversalGroupedRounds.SessionRun reference=org.kanger.ContextUniversalGroupedRounds.runWithValidationReuse(r.x,r.foreign,e.common,e.pools,e.units,e.compounds,r.policy.kernel,r.policy.local,r.policy.rounds,WORK,4096);require(reference.result.status==org.kanger.ContextUniversalGroupedRounds.Status.STABLE_GROUPED_POOLS&&reference.metrics.entries==0,"fresh prior explicit controller reference");same(reference.result,r.chain.trace);}
    static void positive()throws Exception {
        ContextUniversalInitialNativeBoundaryMatrix.Fixture f=new ContextUniversalInitialNativeBoundaryMatrix.Fixture();Policy p=new Policy(f.limits,ContextUniversalGroupedRoundsRunner.local(),8,WORK,4096);List<Snapshot> independent=Arrays.asList(f.a,f.b,f.d);Receipt first=stable(ContextUniversalNativeBranch.run(f.x,independent,p),f.x,independent,p);f.initial(first.initial.entry);f.products(first.chain.trace);manual(first);continued(first);
        Snapshot group=ContextProductionNativeBinding.trusted("native-owning",Arrays.asList(f.d,f.b),WORK);List<Snapshot> trusted=Arrays.asList(group,f.a);Receipt second=stable(ContextUniversalNativeBranch.run(f.x,trusted,p),f.x,trusted,p);f.initial(second.initial.entry);f.products(second.chain.trace);same(first.chain.trace,second.chain.trace);continued(second);
        ContextUniversalSignedAlternativesMatrix.Fixture signed=new ContextUniversalSignedAlternativesMatrix.Fixture(true);List<Snapshot> cuts=Arrays.asList(signed.a,signed.b,signed.d);Policy signedPolicy=policy(8,WORK,4096);Receipt third=stable(ContextUniversalNativeBranch.run(signed.x,cuts,signedPolicy),signed.x,cuts,signedPolicy);signed.products(third.chain.trace);manual(third);continued(third);
        Snapshot self=bind(true,"!~anchor(1);");Policy small=policy(1,WORK,1);Receipt fourth=stable(ContextUniversalNativeBranch.run(self,Collections.emptyList(),small),self,Collections.emptyList(),small);require(fourth.chain.trace.completedRounds==1&&fourth.initial.entry.units.units.isEmpty()&&fourth.initial.entry.compounds.clauses.isEmpty(),"capacity1/self-only complete pipeline with both empty carriers");continued(fourth);
        Map<Cut,Packet> packets=new LinkedHashMap<>();org.kanger.ContextUniversalGroupedRounds.Round last=first.chain.trace.history.get(first.chain.trace.history.size()-1);for(Map.Entry<Cut,ConstraintTransfer> e:last.barrier.branches.entrySet())packets.put(e.getKey(),e.getValue().output);require(ContextWitnessResultTransport.family(last.input,new ArrayList<>(packets.keySet()),WORK).finish(packets,WORK).status==FamilyStatus.INCOMPLETE,"audited supplied branch does NOT grant complete live-family eligibility");
        require(pipelines==4&&checksOfPipeline==4,"four owning stable pipelines plus independent composite rechecks");System.out.println("NATIVE_BRANCH_POSITIVE pipelines="+pipelines+" compositeRechecks="+checksOfPipeline+" manualReferences=2 continuations=4 minimumCertificatesBound=true noLiveEligibility=true");
    }
    static Map<Set<org.kanger.ContextProductionCapture.Source>,Integer> evidence(Rejection r){List<org.kanger.ContextProductionCapture.Support> supports=new ArrayList<>();for(org.kanger.ContextUniversalFrozenConstraints.Proof p:r.proofs){require(p.clause==null,"only actual detached empty proof roots");supports.add(p.support);}return ContextUniversalSourceAlternativesMatrix.supports(supports);}
    static void refusals()throws Exception {
        Snapshot x=bind(true,"!p(1);"),negative=bind(false,"!~p(1);"),bad=bind(false,"!left(1)||right(1);");Policy p=policy(8,WORK,4096);Result initial=ContextUniversalNativeBranch.run(x,Collections.singletonList(negative),p);require(initial.status==Status.REFUTED&&initial.output==null&&initial.refutations.size()==1,"initial rejection cannot expose stable prefix");Rejection initialProof=initial.refutations.get(Cut.of(negative));require(initialProof.phase==RejectionPhase.INITIAL&&initialProof.round==0&&initialProof.xRefuted&&evidence(initialProof).equals(Collections.singletonMap(ContextUniversalSourceAlternativesMatrix.sources(x.primary.get(0).source,negative.primary.get(0).source),1)),"initial route preserves exact empty1 without inventing grouped-round identity");
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(negative,bad),Arrays.asList(bad,negative)))no(ContextUniversalNativeBranch.run(x,order,p),"late unsupported cut suppresses earlier initial refutation");no(ContextUniversalNativeBranch.run(x,Arrays.asList(negative,negative),p),"duplicate physical cut");no(ContextUniversalNativeBranch.run(null,Collections.emptyList(),p),"missing original X");
        Snapshot anchor=bind(true,"!anchor(1);"),yes=bind(false,"!b(1);"),no=bind(false,"!~b(1);");Snapshot group=ContextProductionNativeBinding.trusted("native-foreign-only",Arrays.asList(yes,no),WORK);Result trusted=ContextUniversalNativeBranch.run(anchor,Collections.singletonList(group),p);Rejection foreign=trusted.refutations.get(Cut.of(group));require(trusted.status==Status.REFUTED&&trusted.output==null&&foreign!=null&&foreign.foreignRefuted&&!foreign.xRefuted&&foreign.phase==RejectionPhase.INITIAL&&evidence(foreign).equals(Collections.singletonMap(ContextUniversalSourceAlternativesMatrix.sources(yes.primary.get(0).source,no.primary.get(0).source),1)),"foreign-only rejection retains original Sources, no X anchor contamination");
        Snapshot ux=bind(true,"!anchor(1); !@u p(u);"),rule=bind(false,"!@u p(u)&&b(u)->r(u);"),donor=bind(false,"!b(1);"),opposite=bind(false,"!~r(1);");Map<Cut,Map<Set<org.kanger.ContextProductionCapture.Source>,Integer>> previous=null;
        for(List<Snapshot> cuts:Arrays.asList(Arrays.asList(rule,donor,opposite),Arrays.asList(opposite,donor,rule))){Result r=ContextUniversalNativeBranch.run(ux,cuts,p);require(r.status==Status.REFUTED&&r.output==null&&r.refutations.keySet().equals(new HashSet<>(Arrays.asList(Cut.of(donor),Cut.of(opposite)))),"subsequent sourced rejection routes both qualified cuts atomically");Map<Cut,Map<Set<org.kanger.ContextProductionCapture.Source>,Integer>> actual=new HashMap<>();for(Rejection rejection:r.refutations.values()){require(rejection.phase==RejectionPhase.GROUPED_ROUND&&rejection.round==2&&rejection.xRefuted,"actual next-barrier grouped rejection, no initial/stable prefix");Map<Set<org.kanger.ContextProductionCapture.Source>,Integer> e=evidence(rejection);require(e.equals(Collections.singletonMap(ContextUniversalSourceAlternativesMatrix.sources(ux.primary.get(1).source,rule.primary.get(0).source,donor.primary.get(0).source,opposite.primary.get(0).source),2)),"exact four-Source empty2 preserved by owning router");actual.put(rejection.cut,e);}if(previous!=null)require(previous.equals(actual),"reverse routing preserves whole per-cut rejection evidence");previous=actual;Result limited=ContextUniversalNativeBranch.run(ux,cuts,new Policy(p.kernel,p.local,1,WORK,4096));no(limited,"progressing round limit hides initial and controller prefix");require(limited.phase.equals("grouped-controller"),"bounded grouped failure reports actual owning phase");}
        ContextUniversalFrozenBranch.Limits tinyKernel=new ContextUniversalFrozenBranch.Limits(16,16,16,512,256,1,65536,65536);no(ContextUniversalNativeBranch.run(x,Collections.singletonList(negative),new Policy(tinyKernel,p.local,8,WORK,4096)),"initial work exhaustion is not refutation");Result auditLimit=ContextUniversalNativeBranch.run(anchor,Collections.emptyList(),policy(8,1,4096));no(auditLimit,"initial replay work exhaustion has no assembled prefix");require(auditLimit.phase.equals("initial-audit"),"initial audit owns its own work budget");
        receiptBoundaries();System.out.println("NATIVE_BRANCH_REFUSALS initialAndGroupedEvidence=true reverseRouting=true noPrefixes=true freshMinimumReplay=true");
    }
    static void mutate(Receipt r,Object owner,String name,Object value)throws Exception{Field f=owner.getClass().getDeclaredField(name);f.setAccessible(true);Object old=f.get(owner);f.set(owner,value);try{recheckFails(r,r.x,r.foreign,r.policy,WORK,"fresh composite check refuses altered "+name);}finally{f.set(owner,old);}}
    static void receiptBoundaries()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u);"),a=bind(false,"!@u (p(u)&&b(u)->r(u))&&(p(u)&&r(u)->s(u));"),b=bind(false,"!b(1);");List<Snapshot> cuts=Arrays.asList(a,b);Policy p=policy(8,WORK,4096);Result complete=ContextUniversalNativeBranch.run(x,cuts,p);Receipt r=stable(complete,x,cuts,p);require(r.chain.trace.completedRounds==3,"retained deep three-round actual native pipeline");Result bounded=ContextUniversalNativeBranch.run(x,cuts,policy(8,38000,4096));no(bounded,"successful controller cannot escape failed terminal audit");require(bounded.phase.equals("chain-audit"),"concrete audit budget stop AFTER actual controller completion");
        ContextUniversalNativeBranch.check(r,x,cuts,p,WORK,4096);recheckFails(r,x,Arrays.asList(b,a),p,WORK,"receipt bound to exact original supplied request order");recheckFails(r,bind(true,"!anchor(1); !@u p(u);"),cuts,p,WORK,"equal-valued different original X");recheckFails(r,x,cuts,policy(8,WORK,4096),WORK,"different actual branch policy");recheckFails(r,x,cuts,p,1,"fresh composite budget failure");
        org.kanger.ContextUniversalInitialEntry.Entry other=ContextUniversalInitialEntryAuditMatrix.entry(x,cuts,p.kernel);org.kanger.ContextUniversalInitialEntryAudit.Receipt otherInitial=ContextUniversalInitialEntryAuditMatrix.yes(ContextUniversalInitialEntryAuditMatrix.inspect(other,p.kernel,WORK));mutate(r,r,"initial",otherInitial);
        org.kanger.ContextUniversalGroupedLocalRounds.Certificate candidate=null;for(org.kanger.ContextUniversalGroupedRounds.Round round:r.chain.trace.history)for(org.kanger.ContextUniversalGroupedLocalRounds.Certificate c:round.certificates.values())if(!c.terminal.minima.isEmpty())candidate=c;require(candidate!=null,"actual nonempty terminal native grouped minimum inventory");mutate(r,candidate.terminal,"minima",Collections.emptyList());ContextUniversalNativeBranch.check(r,x,cuts,p,WORK,4096);require(r.chain.trace.output.packet.items.stream().filter(i->i.atom.predicate.equals("s")).flatMap(i->i.proofs.stream()).anyMatch(s->s.depth==2&&s.sources.size()==3),"restored minimum audit retains whole physical-rule s2 Source evidence");
        boolean immutable=false;try{r.foreign.clear();}catch(UnsupportedOperationException expected){immutable=true;}require(immutable,"pipeline copies and seals supplied request inventory");
    }
}
